// swift-tools-version: 6.1
import PackageDescription

let package = Package(
    name: "WordFreq",
    products: [.executable(name: "app", targets: ["app"])],
    targets: [
        .target(name: "WordFreq"),
        .executableTarget(name: "app", dependencies: ["WordFreq"]),
        .testTarget(name: "WordFreqTests", dependencies: ["WordFreq"]),
    ]
)

/// Counts case-insensitive words, where a word is a maximal run of ASCII letters.
///
/// Input may be fed in arbitrary chunks; a word split across chunk boundaries
/// is joined correctly. Every non-letter byte acts as a separator.
public struct WordCounter {
    public private(set) var counts: [String: Int] = [:]
    private var pending: [UInt8] = []

    public init() {
        pending.reserveCapacity(64)
    }

    /// Feeds a chunk of raw bytes.
    public mutating func consume(_ bytes: some Sequence<UInt8>) {
        for byte in bytes {
            if let lower = Self.lowercasedLetter(byte) {
                pending.append(lower)
            } else {
                flush()
            }
        }
    }

    /// Feeds the UTF-8 bytes of a string.
    public mutating func consume(_ text: String) {
        var text = text
        text.withUTF8 { consume($0) }
    }

    /// Completes any word still in progress. Call once input is exhausted.
    public mutating func finish() {
        flush()
    }

    /// The `limit` most frequent words, by count descending then word ascending (byte order).
    public func top(_ limit: Int) -> [(word: String, count: Int)] {
        counts
            .map { (word: $0.key, count: $0.value) }
            .sorted { lhs, rhs in
                lhs.count != rhs.count ? lhs.count > rhs.count : lhs.word.utf8.lexicographicallyPrecedes(rhs.word.utf8)
            }
            .prefix(limit)
            .map { $0 }
    }

    private mutating func flush() {
        guard !pending.isEmpty else { return }
        counts[String(decoding: pending, as: UTF8.self), default: 0] += 1
        pending.removeAll(keepingCapacity: true)
    }

    @inline(__always)
    private static func lowercasedLetter(_ byte: UInt8) -> UInt8? {
        switch byte {
        case UInt8(ascii: "a")...UInt8(ascii: "z"): byte
        case UInt8(ascii: "A")...UInt8(ascii: "Z"): byte | 0x20
        default: nil
        }
    }
}

/// Formats ranked entries as `<count> <word>` lines, each terminated by a newline.
public func formatReport(_ entries: [(word: String, count: Int)]) -> String {
    entries.map { "\($0.count) \($0.word)\n" }.joined()
}

import WordFreq

var counter = WordCounter()
// Invalid UTF-8 is repaired to U+FFFD, whose bytes are all >= 0x80 and thus
// separators, so word boundaries are preserved exactly.
while let line = readLine(strippingNewline: false) {
    counter.consume(line)
}
counter.finish()
print(formatReport(counter.top(10)), terminator: "")

import Testing
import WordFreq

@Suite struct WordCounterTests {
    private func report(_ input: String) -> String {
        var counter = WordCounter()
        counter.consume(input)
        counter.finish()
        return formatReport(counter.top(10))
    }

    @Test func example() {
        #expect(report("The cat and the hat.") == "2 the\n1 and\n1 cat\n1 hat\n")
    }

    @Test func separators() {
        #expect(report("don't stop_me 4now, now-NOW") == "3 now\n1 don\n1 me\n1 stop\n1 t\n")
    }

    @Test func emptyInput() {
        #expect(report("").isEmpty)
        #expect(report("123 ... \u{e9}").isEmpty)
    }

    @Test func wordSplitAcrossChunks() {
        var counter = WordCounter()
        counter.consume(Array("hel".utf8))
        counter.consume(Array("LO wor".utf8))
        counter.consume([0xFF])
        counter.consume(Array("ld".utf8))
        counter.finish()
        #expect(formatReport(counter.top(10)) == "1 hello\n1 ld\n1 wor\n")
    }

    @Test func limitsToTen() {
        let words = (0..<15).map { "w" + String(repeating: "a", count: $0 + 1) }
        #expect(report(words.joined(separator: " ")).split(separator: "\n").count == 10)
    }
}
